def transform(grid):
    """Connect matching non-frame tile colors across aligned tile rows/columns."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    tiles = []

    # Each nonzero tile is a connected component, separated from its neighbors by 0s.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            counts = Counter(grid[y][x] for y, x in cells)
            base = counts.most_common(1)[0][0]
            tile = (min(ys), max(ys), min(xs), max(xs), (min(ys) + max(ys)) // 2,
                    (min(xs) + max(xs)) // 2)
            tiles.append((tile, {color for color in counts if color != base}))

    # For each non-frame color, join the outermost matching tiles on each aligned
    # row and column. Only separator cells are changed; tile contents stay intact.
    for color in sorted({c for _, colors in tiles for c in colors}):
        nodes = [t for t, colors in tiles if color in colors]
        rows = defaultdict(list)
        cols = defaultdict(list)
        for t in nodes:
            y0, y1, x0, x1, cy, cx = t
            rows[cy].append(t)
            cols[cx].append(t)

        for cy, group in rows.items():
            group.sort(key=lambda t: t[4])
            if len(group) >= 2:
                left, right = group[0], group[-1]
                for x in range(left[3] + 1, right[2]):
                    if out[cy][x] == 0:
                        out[cy][x] = color

        for cx, group in cols.items():
            group.sort(key=lambda t: t[4])
            if len(group) >= 2:
                top, bottom = group[0], group[-1]
                for y in range(top[1] + 1, bottom[0]):
                    if out[y][cx] == 0:
                        out[y][cx] = color
    return out
