from collections import Counter, defaultdict, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    marks = []
    totals = Counter()

    # Each tile is one nonzero component. Its most common color is the frame;
    # the remaining color is its inset marker.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            counts = Counter(grid[y][x] for y, x in cells)
            frame = counts.most_common(1)[0][0]
            for color, n in counts.items():
                if color == frame:
                    continue
                pts = [(y, x) for y, x in cells if grid[y][x] == color]
                ys = [y for y, x in pts]
                xs = [x for y, x in pts]
                marks.append((color, min(ys), max(ys), min(xs), max(xs)))
                totals[color] += n

    # The most frequent inset color is the ordinary marker; connect the other
    # marker colors along aligned tile rows and columns.
    if not totals:
        return out
    ordinary = totals.most_common(1)[0][0]
    horizontal = defaultdict(list)
    vertical = defaultdict(list)
    for color, y0, y1, x0, x1 in marks:
        if color == ordinary:
            continue
        horizontal[(color, y0, y1)].append((x0, x1))
        vertical[(color, x0, x1)].append((y0, y1))

    for (color, y0, y1), spans in horizontal.items():
        spans.sort()
        for (_, left1), (right0, _) in zip(spans, spans[1:]):
            for y in range(y0, y1 + 1):
                for x in range(left1 + 1, right0):
                    if out[y][x] == 0:
                        out[y][x] = color

    for (color, x0, x1), spans in vertical.items():
        spans.sort()
        for (_, top1), (bottom0, _) in zip(spans, spans[1:]):
            for x in range(x0, x1 + 1):
                for y in range(top1 + 1, bottom0):
                    if out[y][x] == 0:
                        out[y][x] = color
    return out

